  all_outlays.append(outlays_1987[m])\n    months.append(f\"1987-{m}\")\n\nprint(f\"Total months: {len(all_outlays)}\")\nprint(f\"Date range: {months[0]} to {months[-1]}\")\nprint(f\"\\nMonthly outlays (millions):\")\nfor m, v in zip(months, all_outlays):\n    print(f\"  {m}: {v}\")\n\n# Calculate geometric mean\n# GM = (product of all values)^(1/n)\nproduct = 1\nfor v in all_outlays:\n    product *= v\n\nn = len(all_outlays)\ngeometric_mean = product ** (1/n)\n\nprint(f\"\\nProduct of all values: {product:.2e}\")\nprint(f\"Number of values (n): {n}\")\nprint(f\"Geometric mean: {geometric_mean:.6f} millions\")\nprint(f\"Geometric mean (rounded to thousandth): {round(geometric_mean, 3)} millions\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
